-- Interactive content for the remaining teaching days.
-- Day 14 remains the dedicated final quiz. Videos are deliberately not seeded here.

with seed(day_number, block_type, position, content) as (
  values
    -- Day 2: team
    (2, 'heading', 0, '{"title":"Как рождается продукт","eyebrow":"День 2 из 14"}'::jsonb),
    (2, 'text', 1, '{"markdown":"Над продуктом работает не один человек. У каждой роли своя зона ответственности, а качество зависит от того, как команда передаёт информацию и договаривается."}'::jsonb),
    (2, 'definition', 2, '{"term":"Кросс-функциональная команда","text":"Команда, в которой специалисты разных направлений вместе создают и улучшают продукт."}'::jsonb),
    (2, 'diagram', 3, '{"title":"Путь задачи","steps":["Идея","Требования","Дизайн","Разработка","Тестирование","Релиз","Обратная связь"]}'::jsonb),
    (2, 'example', 4, '{"title":"Пример: смена пароля","expected":"Пользователь меняет пароль по понятным правилам и может войти с новым паролем.","actual":"В требованиях не указано, должен ли старый пароль перестать работать сразу.","conclusion":"QA уточняет правило до разработки — так проверка и реализация будут однозначными."}'::jsonb),
    (2, 'important', 5, '{"title":"QA подключается рано","text":"Чем раньше команда заметит неясность, тем дешевле её исправить. Поэтому QA работает не только с готовой функцией."}'::jsonb),
    (2, 'question', 6, '{"question":"Кто обычно уточняет, какую проблему пользователя должна решить задача?","options":["Product Manager или Product Owner","Только QA","Только DevOps","Пользователь после релиза"],"correctIndex":0,"explanation":"Цель и приоритет задачи обычно определяет PM или PO, а команда помогает уточнить детали."}'::jsonb),
    (2, 'summary', 7, '{"title":"Главное из урока","points":["Продукт создаёт команда специалистов.","QA уточняет требования и проверяет готовый результат.","Задача проходит путь от идеи до обратной связи после релиза."]}'::jsonb),
    (2, 'heading', 8, '{"title":"Проверочный тест","eyebrow":"Закрепляем материал"}'::jsonb),
    (2, 'question', 9, '{"question":"На каком этапе QA может задать вопрос о неясном требовании?","options":["Только после релиза","При обсуждении требований","Только после написания кода","Только после первого бага"],"correctIndex":1,"explanation":"Вопросы к требованиям помогают предотвратить ошибки ещё до реализации."}'::jsonb),
    (2, 'question', 10, '{"question":"Какова роль разработчика в пути задачи?","options":["Определять цену продукта","Реализовать согласованное решение","Проводить только интервью","Выдавать сертификаты"],"correctIndex":1,"explanation":"Разработчик превращает согласованное решение в работающий продукт."}'::jsonb),

    -- Day 3: test cases and checklists
    (3, 'heading', 0, '{"title":"Тест-кейс или чек-лист?","eyebrow":"День 3 из 14"}'::jsonb),
    (3, 'text', 1, '{"markdown":"Тестировщик фиксирует проверки так, чтобы их можно было понять, выполнить и повторить. Для этого чаще всего используют чек-листы и тест-кейсы."}'::jsonb),
    (3, 'definition', 2, '{"term":"Чек-лист","text":"Краткий список того, что нужно проверить. Он помогает не забыть важные пункты."}'::jsonb),
    (3, 'definition', 3, '{"term":"Тест-кейс","text":"Подробное описание проверки: предусловия, шаги, ожидаемый результат и при необходимости тестовые данные."}'::jsonb),
    (3, 'example', 4, '{"title":"Форма входа","expected":"При верных данных пользователь открывает личный кабинет.","actual":"В чек-листе достаточно пункта «Вход с корректными данными». В тест-кейсе нужно описать конкретные данные, шаги и ожидаемый результат.","conclusion":"Инструмент выбирают по риску, сложности и необходимости повторяемости."}'::jsonb),
    (3, 'question', 5, '{"question":"Что обычно содержит тест-кейс?","options":["Только название функции","Шаги и ожидаемый результат","Только скриншот","Только имя автора"],"correctIndex":1,"explanation":"Тест-кейс нужен, чтобы другой человек мог воспроизвести проверку и понять ожидаемый результат."}'::jsonb),
    (3, 'summary', 6, '{"title":"Главное из урока","points":["Чек-лист подходит для быстрого покрытия проверок.","Тест-кейс нужен, когда важна подробность и повторяемость.","У каждой проверки должен быть понятный ожидаемый результат."]}'::jsonb),
    (3, 'homework', 7, '{"title":"Практическое задание","instruction":"Составьте чек-лист из 7 пунктов и два подробных тест-кейса для формы входа с email и паролем.","submitHint":"Отправьте текстом или приложите документ."}'::jsonb),

    -- Day 4: bug reports
    (4, 'heading', 0, '{"title":"Как сообщить о дефекте","eyebrow":"День 4 из 14"}'::jsonb),
    (4, 'text', 1, '{"markdown":"Найти проблему недостаточно. Команде нужно быстро понять, что случилось, как это повторить и насколько срочно исправлять."}'::jsonb),
    (4, 'definition', 2, '{"term":"Баг-репорт","text":"Сообщение о дефекте с данными, которые помогают команде воспроизвести, оценить и исправить проблему."}'::jsonb),
    (4, 'diagram', 3, '{"title":"Состав хорошего баг-репорта","steps":["Понятный заголовок","Предусловия","Шаги","Фактический результат","Ожидаемый результат","Окружение и вложения"]}'::jsonb),
    (4, 'example', 4, '{"title":"Понятное описание проблемы","expected":"После ввода верного промокода скидка 10% применяется к заказу.","actual":"Скидка не меняет сумму заказа в Chrome 126 на Windows 11.","conclusion":"Конкретные шаги и окружение позволяют быстрее воспроизвести дефект."}'::jsonb),
    (4, 'important', 5, '{"title":"Severity и Priority — не одно и то же","text":"Severity показывает влияние дефекта на продукт, Priority — насколько срочно бизнесу нужно исправление."}'::jsonb),
    (4, 'question', 6, '{"question":"Что поможет разработчику быстрее воспроизвести баг?","options":["Фраза «ничего не работает»","Точные шаги, данные и ожидаемый результат","Только имя тестировщика","Ссылка на главную страницу"],"correctIndex":1,"explanation":"Воспроизводимые шаги и ожидаемый результат делают сообщение полезным для команды."}'::jsonb),
    (4, 'summary', 7, '{"title":"Главное из урока","points":["Баг — подтверждённое расхождение между ожидаемым и фактическим результатом.","Хороший баг-репорт конкретен и воспроизводим.","Severity описывает влияние, Priority — срочность исправления."]}'::jsonb),
    (4, 'homework', 8, '{"title":"Практическое задание","instruction":"Найдите один дефект на знакомом сайте или в приложении и оформите баг-репорт: заголовок, шаги, expected, actual, окружение, Severity и Priority.","submitHint":"Если нельзя приложить скриншот, опишите ситуацию максимально точно."}'::jsonb),

    -- Day 5: testing types
    (5, 'heading', 0, '{"title":"Что и зачем проверяем","eyebrow":"День 5 из 14"}'::jsonb),
    (5, 'text', 1, '{"markdown":"Разные проверки отвечают на разные вопросы. Важно не заучить названия, а понимать цель проверки и момент, когда она нужна."}'::jsonb),
    (5, 'definition', 2, '{"term":"Smoke-тестирование","text":"Быстрая проверка критически важных сценариев: можно ли в принципе продолжать тестирование сборки."}'::jsonb),
    (5, 'diagram', 3, '{"title":"Проверки интернет-магазина","steps":["Smoke: сайт открывается и заказ оформляется","Functional: промокод применяет скидку","Regression: старый заказ не сломался после изменения корзины","Integration: оплата передаёт статус заказу","UI: пользователь понимает форму"]}'::jsonb),
    (5, 'example', 4, '{"title":"После изменения корзины","expected":"Добавление товара, расчёт суммы и оформление заказа продолжают работать.","actual":"Разработчик изменил расчёт скидки.","conclusion":"Нужны функциональные проверки новой логики и регрессионные проверки связанных сценариев."}'::jsonb),
    (5, 'question', 5, '{"question":"Для чего проводят smoke-тестирование?","options":["Проверить все детали дизайна","Быстро убедиться, что критические функции работают","Заменить регрессию","Измерить скорость интернета"],"correctIndex":1,"explanation":"Smoke помогает понять, пригодна ли сборка к дальнейшему тестированию."}'::jsonb),
    (5, 'summary', 6, '{"title":"Главное из урока","points":["Functional проверяет выполнение требований.","Smoke быстро проверяет жизнеспособность сборки.","Regression помогает найти поломки в уже работавших частях.","Integration проверяет взаимодействие компонентов."]}'::jsonb),
    (5, 'homework', 7, '{"title":"Практическое задание","instruction":"Для интернет-магазина подберите по одному примеру functional, smoke, regression, integration и UI-проверки.","submitHint":"Опишите действие и ожидаемый результат для каждого примера."}'::jsonb),

    -- Day 6: test design
    (6, 'heading', 0, '{"title":"Как выбрать сильные проверки","eyebrow":"День 6 из 14"}'::jsonb),
    (6, 'text', 1, '{"markdown":"Перебрать абсолютно все значения невозможно. Техники тест-дизайна помогают выбрать небольшой набор проверок, который с высокой вероятностью найдёт проблему."}'::jsonb),
    (6, 'definition', 2, '{"term":"Классы эквивалентности","text":"Группы значений, которые система обрабатывает одинаково. Достаточно проверить представителя каждого класса."}'::jsonb),
    (6, 'example', 3, '{"title":"Поле «Возраст» от 18 до 99","expected":"Система принимает целые значения от 18 до 99 включительно.","actual":"Классы: меньше 18, от 18 до 99, больше 99, пустое или нечисловое значение.","conclusion":"Для каждого класса нужна хотя бы одна проверка."}'::jsonb),
    (6, 'definition', 4, '{"term":"Граничные значения","text":"Значения на границе допустимого диапазона и рядом с ней. Ошибки часто возникают именно там."}'::jsonb),
    (6, 'question', 5, '{"question":"Какие значения особенно важны для поля с диапазоном от 18 до 99?","options":["18 и 99","Только 50","Только отрицательные числа","Только пустое поле"],"correctIndex":0,"explanation":"На границах и рядом с ними часто возникают ошибки: полезно проверить 17, 18, 19, 98, 99 и 100."}'::jsonb),
    (6, 'summary', 6, '{"title":"Главное из урока","points":["Классы эквивалентности сокращают число похожих проверок.","Граничные значения проверяют рискованные края диапазона.","Тест-дизайн помогает проверять осмысленно, а не случайно."]}'::jsonb),
    (6, 'homework', 7, '{"title":"Практическое задание","instruction":"Примените классы эквивалентности и граничные значения к полю «Возраст» с диапазоном от 18 до 99.","submitHint":"Перечислите классы и конкретные тестовые значения."}'::jsonb),

    -- Day 7: client-server
    (7, 'heading', 0, '{"title":"Что происходит после клика","eyebrow":"День 7 из 14"}'::jsonb),
    (7, 'text', 1, '{"markdown":"Когда пользователь нажимает кнопку, браузер не выполняет всю работу сам. Он отправляет запрос серверу, а тот при необходимости обращается к базе данных и возвращает ответ."}'::jsonb),
    (7, 'diagram', 2, '{"title":"Путь запроса","steps":["Пользователь","Frontend в браузере","HTTP-запрос","Backend","База данных","HTTP-ответ","Интерфейс"]}'::jsonb),
    (7, 'definition', 3, '{"term":"Frontend и Backend","text":"Frontend — часть продукта, с которой взаимодействует пользователь. Backend — серверная часть с бизнес-логикой и данными."}'::jsonb),
    (7, 'example', 4, '{"title":"Нажатие «Войти»","expected":"Браузер отправляет логин и пароль, сервер проверяет их и возвращает результат.","actual":"Если пароль неверный, сервер сообщает об ошибке, а интерфейс показывает понятную подсказку.","conclusion":"QA может проверять и интерфейс, и сам запрос с ответом."}'::jsonb),
    (7, 'question', 5, '{"question":"Где обычно хранится постоянная информация о пользователях?","options":["В базе данных","Только в кнопке браузера","В названии вкладки","В скриншоте"],"correctIndex":0,"explanation":"Backend обращается к базе данных, чтобы сохранить или получить состояние продукта."}'::jsonb),
    (7, 'summary', 6, '{"title":"Главное из урока","points":["Клиент отправляет запрос, сервер обрабатывает его и возвращает ответ.","Frontend отвечает за пользовательский интерфейс.","Backend реализует правила и работает с данными."]}'::jsonb),
    (7, 'heading', 7, '{"title":"Проверочный тест","eyebrow":"Закрепляем материал"}'::jsonb),
    (7, 'question', 8, '{"question":"Что происходит после нажатия кнопки «Войти»?","options":["Браузер обычно отправляет запрос серверу","Сразу меняется база данных без сервера","QA получает уведомление автоматически","Страница всегда перезагружается"],"correctIndex":0,"explanation":"Конкретная реализация может различаться, но обычно действие запускает запрос к серверной части."}'::jsonb),
    (7, 'question', 9, '{"question":"Какая часть продукта показывает поля и кнопки?","options":["Frontend","Backend","База данных","HTTP-статус"],"correctIndex":0,"explanation":"Интерфейс, который видит и использует человек, относится к frontend."}'::jsonb),

    -- Day 8: DevTools
    (8, 'heading', 0, '{"title":"DevTools: инструменты тестировщика","eyebrow":"День 8 из 14"}'::jsonb),
    (8, 'text', 1, '{"markdown":"DevTools — встроенные инструменты браузера. Они помогают увидеть структуру страницы, ошибки JavaScript и обмен данными между браузером и сервером."}'::jsonb),
    (8, 'diagram', 2, '{"title":"Три вкладки для старта","steps":["Elements — HTML и CSS","Console — сообщения и ошибки","Network — запросы, ответы и время загрузки"]}'::jsonb),
    (8, 'definition', 3, '{"term":"Network-запрос","text":"Обмен данными между браузером и сервером. В нём можно увидеть URL, метод, статус, заголовки, тело и ответ."}'::jsonb),
    (8, 'example', 4, '{"title":"Почему не сохранилась форма","expected":"После отправки формы сервер возвращает успешный ответ.","actual":"Во вкладке Network виден POST-запрос со статусом 400 и текстом ошибки.","conclusion":"Network помогает отделить проблему интерфейса от ответа сервера."}'::jsonb),
    (8, 'question', 5, '{"question":"Где в DevTools искать JavaScript-ошибки?","options":["Console","Elements","Sources только","Настройках профиля"],"correctIndex":0,"explanation":"Console показывает сообщения, предупреждения и ошибки, возникающие на странице."}'::jsonb),
    (8, 'summary', 6, '{"title":"Главное из урока","points":["Elements помогает исследовать разметку и стили.","Console показывает ошибки и сообщения.","Network показывает, какие запросы отправляет страница и что приходит в ответ."]}'::jsonb),
    (8, 'homework', 7, '{"title":"Практическое задание","instruction":"Откройте DevTools на любом сайте. Найдите один запрос во вкладке Network и опишите URL, метод, статус, Headers и Response.","submitHint":"Можно приложить скриншот или написать ответ текстом."}'::jsonb),

    -- Day 9: API and HTTP
    (9, 'heading', 0, '{"title":"Как программы общаются через API","eyebrow":"День 9 из 14"}'::jsonb),
    (9, 'text', 1, '{"markdown":"API позволяет программам обмениваться данными по понятным правилам. В вебе этот обмен часто происходит через HTTP-запросы и ответы в формате JSON."}'::jsonb),
    (9, 'definition', 2, '{"term":"Endpoint","text":"Конкретный адрес API, к которому обращается клиент: например, /users или /orders/42."}'::jsonb),
    (9, 'diagram', 3, '{"title":"Из чего состоит запрос","steps":["Метод: GET или POST","URL endpoint","Headers","Параметры или Body","HTTP status","JSON-ответ"]}'::jsonb),
    (9, 'example', 4, '{"title":"Создание пользователя","expected":"POST-запрос передаёт данные нового пользователя и получает статус 201 после успешного создания.","actual":"Сервер возвращает 400, если обязательный email не передан.","conclusion":"QA проверяет и успешные, и ошибочные сценарии API."}'::jsonb),
    (9, 'question', 5, '{"question":"Какой HTTP-метод чаще используют для получения списка пользователей?","options":["GET","POST","DELETE","PATCH"],"correctIndex":0,"explanation":"GET запрашивает данные, не создавая и не изменяя ресурс."}'::jsonb),
    (9, 'summary', 6, '{"title":"Главное из урока","points":["API — способ взаимодействия программ.","GET получает данные, POST обычно создаёт, PATCH или PUT изменяет, DELETE удаляет.","Статус-код сообщает результат обработки запроса."]}'::jsonb),
    (9, 'heading', 7, '{"title":"Проверочный тест","eyebrow":"Закрепляем материал"}'::jsonb),
    (9, 'question', 8, '{"question":"Что обычно означает HTTP-статус 404?","options":["Ресурс не найден","Успешное создание","Ошибка авторизации","Внутренняя ошибка сервера"],"correctIndex":0,"explanation":"404 означает, что запрошенный маршрут или ресурс сервер не нашёл."}'::jsonb),
    (9, 'question', 9, '{"question":"В каком формате API часто возвращает структурированные данные?","options":["JSON","Только PNG","Только PDF","Только CSS"],"correctIndex":0,"explanation":"JSON — распространённый текстовый формат для передачи структурированных данных."}'::jsonb),

    -- Day 10: Postman
    (10, 'heading', 0, '{"title":"Первый API-клиент","eyebrow":"День 10 из 14"}'::jsonb),
    (10, 'text', 1, '{"markdown":"Postman позволяет отправлять API-запросы без написания интерфейса. В нём удобно менять метод, URL, заголовки, параметры и тело запроса, а затем читать ответ."}'::jsonb),
    (10, 'definition', 2, '{"term":"Collection","text":"Набор сохранённых запросов в Postman. Коллекция помогает организовать проверки одного API."}'::jsonb),
    (10, 'diagram', 3, '{"title":"Порядок работы","steps":["Выберите метод","Введите URL","Добавьте Params, Headers или Body","Отправьте запрос","Проверьте status и response","Сохраните запрос"]}'::jsonb),
    (10, 'example', 4, '{"title":"GET-запрос к пользователям","expected":"GET https://jsonplaceholder.typicode.com/users возвращает список пользователей и статус 200.","actual":"В Postman статус, headers и JSON видны в одном окне.","conclusion":"Инструмент помогает быстро проверить контракт API независимо от интерфейса."}'::jsonb),
    (10, 'question', 5, '{"question":"Где обычно передают JSON для создания сущности?","options":["В Body POST-запроса","В названии коллекции","В цвете кнопки Send","В ответе сервера"],"correctIndex":0,"explanation":"Данные, которые клиент отправляет серверу, обычно передают в теле POST, PUT или PATCH запроса."}'::jsonb),
    (10, 'summary', 6, '{"title":"Главное из урока","points":["Postman отправляет запросы к API и показывает ответы.","Params, Headers и Body меняют состав запроса.","Сохранённые запросы объединяют в коллекции."]}'::jsonb),
    (10, 'homework', 7, '{"title":"Практическое задание","instruction":"Сделайте GET-запрос к https://jsonplaceholder.typicode.com/users. Затем выполните POST-запрос с JSON-body и приложите скриншоты или экспорт коллекции.","submitHint":"В ответе укажите URL, метод, status и что вернул сервер."}'::jsonb),

    -- Day 11: SQL
    (11, 'heading', 0, '{"title":"Проверяем данные в базе","eyebrow":"День 11 из 14"}'::jsonb),
    (11, 'text', 1, '{"markdown":"База данных хранит состояние продукта: пользователей, заказы, статусы и связи между ними. QA не обязан быть разработчиком базы, но должен уметь прочитать данные и проверить гипотезу."}'::jsonb),
    (11, 'definition', 2, '{"term":"SQL","text":"Язык запросов к реляционным базам данных. Он помогает получать, фильтровать, сортировать и связывать данные."}'::jsonb),
    (11, 'diagram', 3, '{"title":"Базовый запрос","steps":["SELECT — какие поля получить","FROM — из какой таблицы","WHERE — по какому условию","ORDER BY — как отсортировать"]}'::jsonb),
    (11, 'example', 4, '{"title":"Проверка заказов пользователя","expected":"Нужно увидеть пользователя и все его заказы.","actual":"Таблицы users и orders связаны по user_id.","conclusion":"JOIN объединяет данные из связанных таблиц в одном результате."}'::jsonb),
    (11, 'question', 5, '{"question":"Какая часть SQL-запроса фильтрует строки по условию?","options":["WHERE","SELECT","ORDER BY","JOIN"],"correctIndex":0,"explanation":"WHERE оставляет в результате только строки, которые подходят под условие."}'::jsonb),
    (11, 'summary', 6, '{"title":"Главное из урока","points":["SELECT получает данные из таблицы.","WHERE фильтрует, ORDER BY сортирует.","JOIN помогает проверить связанные сущности: например, пользователя и его заказы."]}'::jsonb),
    (11, 'homework', 7, '{"title":"Практическое задание","instruction":"Напишите запросы: выбрать пользователей по условию, отсортировать их и получить пользователей вместе с их заказами через JOIN.","submitHint":"Можно использовать вымышленные имена таблиц users и orders."}'::jsonb),

    -- Day 12: methodologies
    (12, 'heading', 0, '{"title":"Как команда организует работу","eyebrow":"День 12 из 14"}'::jsonb),
    (12, 'text', 1, '{"markdown":"Методология задаёт команде ритм работы: как планировать задачи, обсуждать результат и реагировать на изменения. QA участвует в процессе, а не ждёт готовую задачу в конце."}'::jsonb),
    (12, 'definition', 2, '{"term":"Agile","text":"Подход, в котором команда поставляет продукт небольшими частями, получает обратную связь и корректирует план."}'::jsonb),
    (12, 'diagram', 3, '{"title":"Scrum-спринт","steps":["Планирование","Работа над задачами","Daily","Тестирование","Демонстрация","Ретроспектива"]}'::jsonb),
    (12, 'example', 4, '{"title":"QA в спринте","expected":"До разработки QA понимает критерии готовности, во время работы уточняет риски, после сборки проверяет сценарии.","actual":"Если QA подключается только в последний день, неясности и дефекты обнаруживаются слишком поздно.","conclusion":"Вовлечённость QA в течение спринта снижает риск сюрпризов перед релизом."}'::jsonb),
    (12, 'question', 5, '{"question":"Какова цель ежедневной встречи в Scrum?","options":["Синхронизировать работу и заметить препятствия","Написать весь код за день","Провести финальный экзамен","Заменить планирование"],"correctIndex":0,"explanation":"Daily помогает команде коротко синхронизироваться и вовремя заметить блокировки."}'::jsonb),
    (12, 'summary', 6, '{"title":"Главное из урока","points":["Waterfall идёт последовательными этапами.","Agile работает короткими итерациями с обратной связью.","Scrum использует спринты, а Kanban визуализирует поток задач.","QA помогает команде в течение всего процесса."]}'::jsonb),
    (12, 'heading', 7, '{"title":"Проверочный тест","eyebrow":"Закрепляем материал"}'::jsonb),
    (12, 'question', 8, '{"question":"Что такое спринт в Scrum?","options":["Короткий ограниченный по времени цикл работы","Название базы данных","Тип HTTP-запроса","Файл с баг-репортами"],"correctIndex":0,"explanation":"Спринт — короткий рабочий цикл, в котором команда создаёт часть ценности продукта."}'::jsonb),
    (12, 'question', 9, '{"question":"Что помогает Kanban?","options":["Визуализировать поток задач и замечать перегрузку","Заменить все тест-кейсы","Хранить пароли","Измерить производительность браузера"],"correctIndex":0,"explanation":"Kanban-доска делает движение задач видимым и помогает ограничивать работу в процессе."}'::jsonb),

    -- Day 13: first QA day
    (13, 'heading', 0, '{"title":"Твой первый день QA","eyebrow":"День 13 из 14"}'::jsonb),
    (13, 'text', 1, '{"markdown":"Рабочая задача редко состоит из одного действия. QA проходит путь от понимания требований до понятного результата для команды: проверяет, исследует, фиксирует и сообщает о рисках."}'::jsonb),
    (13, 'diagram', 2, '{"title":"Рабочий маршрут QA","steps":["Прочитать задачу","Уточнить условия","Составить проверки","Протестировать","Исследовать через DevTools и API","Проверить данные","Оформить результат"]}'::jsonb),
    (13, 'important', 3, '{"title":"Сначала — ясность","text":"Перед стартом убедитесь, что понимаете цель задачи, критерии готовности, ограничения и данные для проверки."}'::jsonb),
    (13, 'example', 4, '{"title":"Задача: регистрация пользователя","expected":"Пользователь с корректными данными создаёт учётную запись и получает понятный результат.","actual":"QA проверяет обычные и граничные данные, смотрит запрос регистрации, при необходимости сверяет запись в базе и оформляет найденные дефекты.","conclusion":"Одна задача объединяет навыки курса в последовательный рабочий процесс."}'::jsonb),
    (13, 'question', 5, '{"question":"С чего разумно начать работу QA над новой задачей?","options":["С понимания цели и требований","С удаления тестовых данных","Сразу с баг-репорта","С публикации релиза"],"correctIndex":0,"explanation":"Без понимания ожидаемого результата невозможно выбрать правильные проверки."}'::jsonb),
    (13, 'summary', 6, '{"title":"Главное из урока","points":["QA начинает с анализа задачи и вопросов к условиям.","Проверки включают основной, негативный и граничный сценарии.","Результат работы QA должен быть понятен команде: что проверено, что найдено и какие риски остались."]}'::jsonb),
    (13, 'homework', 7, '{"title":"Практическое задание","instruction":"Выполните сквозную задачу: составьте чек-лист минимум из 10 проверок для формы регистрации, опишите 2 баг-репорта и укажите, что проверите через DevTools, API и SQL.","submitHint":"Отправьте один структурированный документ или текст с разделами."}'::jsonb)
)
insert into public.lesson_blocks (lesson_id, block_type, position, content)
select lesson.id, seed.block_type, seed.position, seed.content
from seed
join public.lessons lesson on lesson.day_number = seed.day_number
where not exists (
  select 1
  from public.lesson_blocks existing
  where existing.lesson_id = lesson.id
);
